let cinematicTheme=true;try{cinematicTheme=localStorage.getItem('nextstep-appearance')!=='light'}catch{}
function syncTheme(){document.body.classList.toggle('cinema',cinematicTheme);const b=document.querySelector('#theme-switch');b.setAttribute('aria-pressed',String(cinematicTheme));b.setAttribute('aria-label',cinematicTheme?'Switch to light theme':'Switch to cinematic dark theme');b.innerHTML=`<i data-lucide="${cinematicTheme?'sun':'moon'}" aria-hidden="true"></i><span>${cinematicTheme?'Light theme':'Cinematic dark'}</span>`;window.lucide?.createIcons()}
document.querySelector('#theme-switch').onclick=()=>{cinematicTheme=!cinematicTheme;try{localStorage.setItem('nextstep-appearance',cinematicTheme?'cinema':'light')}catch{}syncTheme();playScene()};
function playScene(){if(document.body.classList.contains('quiet')||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const s=document.createElement('div');s.className='scene-sweep';s.setAttribute('aria-hidden','true');document.body.appendChild(s);s.addEventListener('animationend',()=>s.remove())}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(b?.id==='motion'||document.body.classList.contains('quiet')||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;if(b?.matches('[data-go],[data-lesson],#understand,#see-example,#select-domain,[data-project-step]'))playScene();if(!cinematicTheme)return;const target=b||e.target,rect=target.getBoundingClientRect(),x=e.detail===0?rect.left+rect.width/2:e.clientX,y=e.detail===0?rect.top+rect.height/2:e.clientY;for(let n=0;n<6;n++){const dot=document.createElement('span');dot.className='cinema-spark';dot.style.left=x+'px';dot.style.top=y+'px';const a=n*Math.PI/3;dot.style.setProperty('--dx',Math.cos(a)*43+'px');dot.style.setProperty('--dy',Math.sin(a)*43+'px');document.body.appendChild(dot);dot.addEventListener('animationend',()=>dot.remove())}const pulse=document.createElement('span');pulse.className='cinema-pulse';pulse.style.left=x+'px';pulse.style.top=y+'px';document.body.appendChild(pulse);pulse.addEventListener('animationend',()=>pulse.remove())},true);
syncTheme();
